const nav = document.querySelector("#nav");
const modal = document.querySelector("#modal");
const modalBody = document.querySelector("#modalBody");
let data = { menu:{}, accounts:{}, account_payments:{}, sales:{}, kitchen:{}, cash:{}, stock_movements:{}, stock_items:{}, recipes:{}, employees:{}, staff_shifts:{}, device_access:{} };
