let accountTypeView = "customer";
let stockView = "current";
let pendingInvoice = null;
let cart = (()=>{try{return JSON.parse(localStorage.getItem("saleCart")||"{}")||{}}catch{return {}}})();

const esc = (v="") => systemLabel(v).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const systemLabel = value => String(value||"").replace(/^Cadernetas?$/i,"Fiado");
const money = value => Number(value||0).toLocaleString("pt-BR",{style:"currency",currency:"BRL"});
const stockUnitLabel=(unit,quantity)=>{const labels={un:["unidade","unidades"],lata:["lata","latas"],"latão":["latão","latões"],garrafa:["garrafa","garrafas"],"galão":["galão","galões"],pacote:["pacote","pacotes"],caixa:["caixa","caixas"],fardo:["fardo","fardos"]},pair=labels[unit];return pair?(Number(quantity)===1?pair[0]:pair[1]):unit||"un"};
const stockPackageLabel=item=>Number(item.package_size)>0?`${Number(item.package_size).toLocaleString("pt-BR")} ${item.package_measure||"ml"} por ${stockUnitLabel(item.unit,1)}`:"";
const date = value => value ? new Date(`${value}${value.length===10?'T12:00':''}`).toLocaleString("pt-BR",{dateStyle:"short",timeStyle:value.length>10?"short":undefined}) : "—";
const time = value => value ? new Date(value).toLocaleTimeString("pt-BR",{hour:"2-digit",minute:"2-digit"}) : "—";
const entries = object => Object.entries(object||{});
const accountCharges = account => (account.items||[]).filter(item=>!item.cancelled_at).reduce((sum,item)=>sum+Number(item.quantity)*Number(item.price),0);
const accountPaid = account => Number(account.payments_total||0);
const accountBalance = account => Math.max(0,Math.round((accountCharges(account)-accountPaid(account))*100)/100);
const accountPayments = id => entries(data.account_payments).filter(([,payment])=>payment.account_id===id&&!payment.voided_at).sort((a,b)=>(b[1].created_at||"").localeCompare(a[1].created_at||""));
const accountActiveItems = account => (account.items||[]).filter(item=>!item.cancelled_at);
const accountLastConsumption = account => accountActiveItems(account).reduce((latest,item)=>(item.created_at||"")>latest?item.created_at:latest,"");
function accountUnpaidItems(account){let covered=accountPaid(account);return accountActiveItems(account).slice().sort((a,b)=>(a.created_at||"").localeCompare(b.created_at||"")).filter(item=>{const total=Number(item.quantity||0)*Number(item.price||0);if(covered>=total-.001){covered-=total;return false}covered=0;return true})}
function accountStatus(account){return account.blocked===true?{label:"Bloqueada",className:"negative",rank:0}:{label:"Em aberto",className:"pending",rank:1}}
function groupedAccountOrders(items){const groups=new Map();for(const item of items){const key=item.order_id||item.id||item.created_at,current=groups.get(key)||{id:key,created_at:item.created_at,created_by:item.created_by||"Caixa principal",items:[],total:0};current.items.push(item);current.total+=Number(item.quantity||0)*Number(item.price||0);groups.set(key,current)}return[...groups.values()].sort((a,b)=>(b.created_at||"").localeCompare(a.created_at||""))}
const activeCash = () => entries(data.cash).sort((a,b)=>(b[1].opened_at||"").localeCompare(a[1].opened_at||"")).find(([,c])=>c.status==="open");
const cashProject = cash => cash?.project_code==="bagaco_laranja"?"Bagaço da Laranja":"Adega Camisa 10";
const category = item => item.category || (/por[cç][aã]o|batata|carne|frango|lanche|comida/i.test(item.name)?"Comidas":"Bebidas");
const productStockState = id => {const recipe=data.recipes[id];if(!recipe?.components?.length)return{available:Infinity,reason:"Sem controle de estoque",tracked:false};const parts=recipe.components.map(c=>({item:data.stock_items[c.stock_item_id],needed:Number(c.quantity||0)}));const missing=parts.find(x=>!x.item);if(missing)return{available:0,reason:"Insumo removido",tracked:true};const limiting=parts.sort((a,b)=>(Number(a.item.stock_quantity||0)/a.needed)-(Number(b.item.stock_quantity||0)/b.needed))[0],available=Math.max(0,Math.floor(Math.min(...parts.map(x=>Number(x.item.stock_quantity||0)/x.needed))));return{available,reason:available<=0?`Falta ${limiting.item.name}`:"",tracked:true}};
const productAvailability = id => productStockState(id).available;
const statusName = {pending:"Pendente",started:"Em andamento",ready:"Pronto",delivered:"Entregue",done:"Concluído"};
const cartLines = () => entries(cart).filter(([id,line])=>data.menu[id]&&Number(line.quantity)>0);
const cartQuantity = () => cartLines().reduce((sum,[,line])=>sum+Number(line.quantity),0);
const cartTotal = () => cartLines().reduce((sum,[id,line])=>sum+Number(line.quantity)*Number(data.menu[id].price),0);
function saveCart(){localStorage.setItem("saleCart",JSON.stringify(cart))}
function changeCart(id,delta){const current=cart[id]||{},next=Number(current.quantity||0)+delta,state=productStockState(id),available=state.available;if(delta>0&&next>available){toast(state.reason||`Disponível para venda: ${available} unidade(s).`,true);return}if(next>0)cart[id]={...current,quantity:next};else delete cart[id];saveCart();draw()}
const kitchenViewOpen = () => module==="Cozinha" || module==="Admin"&&page==="kitchen";
function prepareKitchenAlerts(){
  knownKitchenOrderIds=new Set(Object.keys(data.kitchen||{}));
  const AudioContext=window.AudioContext||window.webkitAudioContext;
  if(!AudioContext)return;
  kitchenAudioContext ||= new AudioContext();
  if(kitchenAudioContext.state==="suspended")kitchenAudioContext.resume().catch(()=>{});
}
function playKitchenAlert(){
  const context=kitchenAudioContext;
  if(!context||context.state!=="running")return;
  const start=context.currentTime+.02;
  const compressor=context.createDynamicsCompressor(),master=context.createGain();
  compressor.threshold.value=-18;compressor.knee.value=12;compressor.ratio.value=8;
  compressor.attack.value=.002;compressor.release.value=.25;
  master.gain.value=1;
  master.connect(compressor).connect(context.destination);
  [0,.72].forEach((strike,index)=>{
    const base=index?1046.5:880;
    [[1,.72],[2,.28],[2.4,.2],[3,.13],[4.2,.08]].forEach(([ratio,level])=>{
      const oscillator=context.createOscillator(),gain=context.createGain(),at=start+strike;
      oscillator.type="sine";oscillator.frequency.value=base*ratio;
      gain.gain.setValueAtTime(.0001,at);
      gain.gain.exponentialRampToValueAtTime(level,at+.008);
      gain.gain.exponentialRampToValueAtTime(.0001,at+1.35);
      oscillator.connect(gain).connect(master);
      oscillator.start(at);oscillator.stop(at+1.4);
    });
  });
}
function prepareFrontAlerts(){
  if(!knownFrontKitchenStatuses)knownFrontKitchenStatuses=new Map(entries(data.kitchen).map(([id,order])=>[id,order.status||"pending"]));
  const AudioContext=window.AudioContext||window.webkitAudioContext;
  if(!AudioContext)return;
  kitchenAudioContext ||= new AudioContext();
  if(kitchenAudioContext.state==="suspended")kitchenAudioContext.resume().catch(()=>{});
}
function playReadyAlert(){
  const context=kitchenAudioContext;
  if(context&&context.state==="running"){
    const start=context.currentTime+.02,master=context.createGain();
    master.gain.value=.65;master.connect(context.destination);
    [659.25,783.99,1046.5].forEach((frequency,index)=>{
      const oscillator=context.createOscillator(),gain=context.createGain(),at=start+index*.18;
      oscillator.type="sine";oscillator.frequency.value=frequency;
      gain.gain.setValueAtTime(.0001,at);gain.gain.exponentialRampToValueAtTime(.7,at+.015);gain.gain.exponentialRampToValueAtTime(.0001,at+.55);
      oscillator.connect(gain).connect(master);oscillator.start(at);oscillator.stop(at+.6);
    });
  }
  navigator.vibrate?.([250,100,250]);
}
function notifyReadyOrder(id,order){
  playReadyAlert();
  const customer=order.customer_name||"Cliente não informado",message=`Pedido de ${customer} está pronto para entrega.`;
  toast(`Pedido pronto: ${customer}`);
  if("Notification"in window&&Notification.permission==="granted"){
    try{new Notification("Pedido pronto para entrega",{body:message,tag:`ready-${id}`,renotify:true})}catch{}
  }
}
function notificationAction(){
  if(!("Notification"in window)||Notification.permission==="granted")return"";
  return`<button class="notification-enable ${Notification.permission==="denied"?'danger':''}" data-enable-notifications>${Notification.permission==="denied"?'Notificações bloqueadas':'Ativar notificações'}</button>`;
}

async function load(render=true){
  const response=await fetch("/api/state",{headers:{...(originToken?{"x-staff-access":originToken}:{}),...(deviceToken?{"x-device-access":deviceToken}:{}),...(token?{authorization:`Bearer ${token}`}:{})}});
  if(!response.ok){
    if(originToken){originToken="";localStorage.removeItem("staffAccessToken");history.replaceState({},"",location.pathname);module=null;page=null;if(render){draw();toast("O caixa foi fechado. O acesso deste aparelho foi encerrado.",true)}}
    else if(token||deviceToken){token="";deviceToken="";deviceRole="";localStorage.removeItem("adminToken");sessionStorage.removeItem("adminToken");localStorage.removeItem("deviceAccessToken");localStorage.removeItem("deviceRole");module=null;page=null;if(render){draw();toast("Sua autorização expirou ou foi revogada.",true)}}
    throw new Error("Não foi possível carregar os dados.");
  }
  const nextData=await response.json();
  if(kitchenViewOpen()){
    const nextIds=new Set(Object.keys(nextData.kitchen||{}));
    if(knownKitchenOrderIds&&[...nextIds].some(id=>!knownKitchenOrderIds.has(id)))playKitchenAlert();
    knownKitchenOrderIds=nextIds;
  }
  if(module==="Frente de caixa"){
    const nextStatuses=new Map(entries(nextData.kitchen).map(([id,order])=>[id,order.status||"pending"]));
    if(knownFrontKitchenStatuses)for(const[id,order]of entries(nextData.kitchen))if((order.status||"pending")==="ready"&&knownFrontKitchenStatuses.get(id)!=="ready")notifyReadyOrder(id,order);
    knownFrontKitchenStatuses=nextStatuses;
  }
  data=nextData;
  if(originToken&&!activeCash()){
    originToken="";localStorage.removeItem("staffAccessToken");history.replaceState({},"",location.pathname);module=null;page=null;
    if(render)toast("O caixa foi fechado. O acesso deste aparelho foi encerrado.",true);
  }
  if(render) draw();
}
async function claimInvite(){
  if(!inviteToken)return;
  const response=await fetch("/api/staff/claim",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({invite_token:inviteToken})});
  const result=await response.json();
  inviteToken="";history.replaceState({},"",location.pathname);
  if(!response.ok)throw new Error(result.error||"Não foi possível ativar este QR Code.");
  originToken=result.access_token;staffDeviceManaged=true;localStorage.setItem("staffAccessToken",originToken);localStorage.setItem("staffDeviceManaged","true");
}
async function mutate(payload, admin=false){
  const response=await fetch("/api/mutate",{method:"POST",headers:{"content-type":"application/json",...(token?{authorization:`Bearer ${token}`}:{}) ,...(deviceToken?{"x-device-access":deviceToken}:{}),...(originToken?{"x-staff-access":originToken}:{})},body:JSON.stringify(payload)});
  const result=await response.json();if(response.status===401&&(token||deviceToken)){token="";deviceToken="";deviceRole="";localStorage.removeItem("adminToken");sessionStorage.removeItem("adminToken");localStorage.removeItem("deviceAccessToken");localStorage.removeItem("deviceRole");module=null;page=null;draw();throw new Error("Sua autorização expirou. Entre novamente.")}if(!response.ok){if(originToken&&/acesso|caixa.*fechado|revog/i.test(result.error||"")){originToken="";localStorage.removeItem("staffAccessToken");history.replaceState({},"",location.pathname);module=null;page=null;draw()}throw new Error(result.error||"Operação não concluída.");}
  await load(false); toast("Alteração salva."); return result;
}
function toast(message,error=false){const box=document.querySelector("#toast");box.textContent=message;box.className=error?"show error":"show";setTimeout(()=>box.className="",2800)}
function openModal(html){const labels=String(html).replace(/Cadernetas/g,"Fiado").replace(/cadernetas/g,"fiados").replace(/Caderneta/g,"Fiado").replace(/caderneta/g,"fiado");modalBody.innerHTML=`<div class="modal-content">${labels}</div>`;if(!modal.open)modal.showModal()}
function closeModal(){modal.close();modalBody.innerHTML=""}
function heading(title,action=""){return `<div class="section-head"><div><div class="eyebrow">${esc(module||"Sistema")}</div><h1>${esc(title)}</h1></div>${action}</div>`}
function empty(text){return `<div class="empty">${esc(text)}</div>`}
function bagacoLandingPage(){return`<section class="bagaco-landing" role="status" aria-label="Carregando o projeto Bagaço da Laranja"><picture><source media="(max-width:700px)" srcset="/bagaco-da-laranja.png"><img src="/bagaco-da-laranja-wide.png" alt="O Bagaço da Laranja"></picture><div class="bagaco-loading"><span class="landing-spinner" aria-hidden="true"></span><b>Carregando o projeto…</b></div></section>`}

function portal(){
  if(originToken){module="Frente de caixa";page="sales";draw();return}
  if(deviceToken){module=deviceRole==="kitchen"?"Cozinha":"Frente de caixa";page=deviceRole==="kitchen"?"kitchen":"sales";draw();return}
  if(staffDeviceManaged&&!token){nav.innerHTML="";app.innerHTML=`<section class="portal staff-access-ended"><div class="access-ended-icon">×</div><div class="eyebrow">Acesso da equipe encerrado</div><h1>Este caixa foi fechado</h1><p class="subtitle">O acesso deste dispositivo terminou junto com o caixa em que o QR Code foi gerado.</p><div class="notice"><b>Para trabalhar novamente:</b> leia o QR Code gerado no próximo caixa.</div><button data-owner-login>Entrar como proprietário</button></section>`;return}
  if(!token){nav.innerHTML="";app.innerHTML=loginPage();return}
  nav.innerHTML="";
  app.innerHTML=`<section class="portal"><div class="eyebrow">Operação integrada</div><h1>Escolha o módulo desta máquina</h1><p class="subtitle">Cada tela acompanha os mesmos dados em tempo real.</p><div class="module-grid">
    ${[["Frente de caixa","Vendas, fiado e acompanhamento de pedidos."],["Cozinha","Fila de preparo com atualização automática."],["Admin","Cardápio, caixa e relatórios."]].map(([name,desc])=>`<button class="module-card" data-module="${name}"><span>ACESSAR</span><b>${name}</b><span>${desc}</span></button>`).join("")}
  </div></section>`;
}
function setupNav(items){nav.innerHTML=items.map(([key,label])=>`<button data-page="${key}" class="${page===key?'nav-active':''}">${label}</button>`).join("")+(deviceToken?`<button data-device-logout class="ghost">Sair</button>`:`<button data-home class="ghost">Módulos</button>`)}
function draw(){
  clearInterval(refreshTimer);
  app.classList.toggle("bagaco-operation",activeCash()?.[1]?.project_code==="bagaco_laranja");
  if(!module)return portal();
  if(module==="Frente de caixa"){
    page ||= "sales"; const ready=entries(data.kitchen).filter(([,o])=>(o.status||"pending")==="ready").length; setupNav([["sales","Saídas"],["accounts","Fiado"],["frontKitchen",`Pedidos${ready?` (${ready})`:""}`]]);
    app.innerHTML=page==="sales"?salesPage():page==="accounts"?accountsPage():frontKitchenPage();
    refreshTimer=setInterval(()=>load(true).catch(()=>{}),3000);
  }else if(module==="Cozinha"){
    page="kitchen";setupNav([]);app.innerHTML=kitchenPage();refreshTimer=setInterval(()=>load(true).catch(()=>{}),3000);
  }else if(module==="Impressora"){
    page="printer";setupNav([]);app.innerHTML=printerPage();refreshTimer=setInterval(()=>load(true).catch(()=>{}),3000);queueAutomaticPrint();
  }else{
    if(!token){setupNav([]);app.innerHTML=loginPage();return}
    page ||= "summary";setupNav([]);
    const content=page==="summary"?overviewPage():page==="menu"?menuPage():page==="stock"?intelligentStockPage():page==="cash"?cashPage():page==="accounts"?accountsPage():page==="staff"?staffPageSimple():page==="devices"?devicesPage():page==="kitchen"?kitchenPage():printerPage();
    app.innerHTML=adminShell(content);
    if(page==="summary"||page==="stock")refreshTimer=setInterval(()=>load(true).catch(()=>{}),3000);
    if(page==="kitchen")refreshTimer=setInterval(()=>load(true).catch(()=>{}),3000);
    if(page==="adminPrinter"){refreshTimer=setInterval(()=>load(true).catch(()=>{}),3000);queueAutomaticPrint()}
  }
}

function adminShell(content){const groups=[["Operação",[["summary","Visão geral"],["cash","Controle de caixa"],["stock","Estoque"]]],["Cadastros",[["menu","Cardápio"],["accounts","Fiado"],["staff","Equipe e diárias"],["devices","Dispositivos"]]]];return `<div class="admin-layout"><aside class="admin-sidebar"><div class="admin-identity"><span class="eyebrow">Administração</span><b>Controle da Adega</b></div>${groups.map(([label,items])=>`<div class="admin-nav-group"><small>${label}</small>${items.map(([key,text])=>`<button data-page="${key}" class="${page===key?'nav-active':''}">${text}</button>`).join("")}</div>`).join("")}<button class="ghost admin-logout" data-admin-logout>Sair do Admin</button></aside><section class="admin-content">${content}</section></div>`}

function salesPage(){
  const open=activeCash();
  const query=saleSearch.toLocaleLowerCase(),products=entries(data.menu).filter(([,item])=>(saleCategory==="Todos"||saleCategory===category(item))&&(!query||item.name.toLocaleLowerCase().includes(query))).sort((a,b)=>a[1].name.localeCompare(b[1].name));
  const catalog=`<div class="sales-toolbar"><div class="product-search"><span>⌕</span><input data-product-search value="${esc(saleSearch)}" placeholder="Buscar produto..." autocomplete="off"></div><div class="category-tabs">${["Todos","Bebidas","Comidas"].map(value=>`<button data-sale-category="${value}" class="${saleCategory===value?'nav-active':''}">${value}</button>`).join("")}</div></div><div class="product-grid">${products.map(([id,item])=>{const state=productStockState(id),available=state.available,out=available<=0;return`<article class="product-wrap ${out?'stock-out':''}"><button class="product-tile" data-cart-add="${id}" ${out?'disabled':''}><span class="product-category">${category(item)}</span><b>${esc(item.name)}</b><strong>${money(item.price)}</strong><small>${out?esc(state.reason):state.tracked?`${available} venda(s) disponíveis`:'Sem controle de estoque'}</small></button></article>`}).join("")||empty("Nenhum produto encontrado.")}</div>`;
  const lines=cartLines();
  const cartPanel=`<aside class="cart-panel"><div class="cart-title"><div><span class="eyebrow">Pedido atual</span><h2>${cartQuantity()} ${cartQuantity()===1?'item':'itens'}</h2></div>${lines.length?`<button class="ghost" data-cart-clear>Limpar</button>`:""}</div><div class="cart-lines">${lines.map(([id,line])=>{const item=data.menu[id];return `<div class="cart-line"><div><b>${esc(item.name)}</b><small>${money(item.price)} cada</small>${line.note?`<em>${esc(line.note)}</em>`:""}<div class="item-secondary-actions"><button class="item-note-button" data-cart-note="${id}">${line.note?'Editar observação':'+ Observação'}</button><button class="item-remove-button" data-cart-remove="${id}">Remover</button></div></div><div class="quantity-control"><button data-cart-minus="${id}" aria-label="Diminuir">−</button><b>${line.quantity}</b><button data-cart-add="${id}" aria-label="Aumentar">+</button></div><b>${money(Number(line.quantity)*Number(item.price))}</b></div>`}).join("")||`<p class="muted">Adicione produtos para montar o pedido.</p>`}</div><div class="cart-total"><span>Total</span><b>${money(cartTotal())}</b></div><button class="primary checkout-button" data-open-checkout ${lines.length?'':'disabled'}>Finalizar pedido</button></aside>`;
  const mobileCheckout=lines.length?`<button class="mobile-checkout" data-open-mobile-cart><span>Ver pedido · ${cartQuantity()} itens</span><b>${money(cartTotal())}</b></button>`:"";
  const ready=entries(data.kitchen).filter(([,o])=>(o.status||"pending")==="ready").length,preparing=entries(data.kitchen).filter(([,o])=>["pending","started"].includes(o.status||"pending")).length;
  return heading("Frente de caixa",`<div class="front-heading-actions">${notificationAction()}${lines.length?`<button class="primary desktop-order-button" data-open-checkout>Pedido · ${cartQuantity()} itens</button>`:""}</div>`)+(!open?`<div class="cash-closed-alert" role="alert"><span class="cash-closed-icon" aria-hidden="true">!</span><div><b>Caixa fechado</b><p>Não é possível receber pagamentos em Dinheiro, Pix ou Cartão. Abra o caixa em <strong>Admin → Caixa</strong> para registrar vendas. Pedidos no fiado continuam disponíveis.</p></div></div>`:`<p class="muted">Caixa aberto desde ${date(open[1].opened_at)}.</p>`)+`${ready?`<button class="notice checkout-button" data-page="frontKitchen"><b>${ready} pedido${ready===1?'':'s'} pronto${ready===1?'':'s'} para entrega</b> · abrir acompanhamento</button>`:`<p class="muted">Cozinha: ${preparing} pedido${preparing===1?'':'s'} em preparo.</p>`}`+`<div class="sales-layout"><div>${catalog}</div>${cartPanel}</div>${mobileCheckout}`;
}
function cartNoteDialog(id){const item=data.menu[id],line=cart[id];if(!item||!line)return;openModal(`<h2>Observação do item</h2><p><b>${line.quantity}x ${esc(item.name)}</b></p><form data-form="cart-note"><input type="hidden" name="id" value="${id}"><input type="hidden" name="return_to_cart" value="${window.innerWidth<=700?'1':''}"><div class="field"><label>Instrução específica</label><textarea name="note" autofocus placeholder="Ex.: uma sem queijo, carne bem passada...">${esc(line.note||"")}</textarea></div><button class="primary checkout-button" type="submit">Salvar observação</button></form>`)}
function mobileCartDialog(){const lines=cartLines();if(!lines.length){if(modal.open)closeModal();draw();return}const rows=lines.map(([id,line])=>{const item=data.menu[id];return`<div class="mobile-cart-line"><div><b>${esc(item.name)}</b><small>${money(item.price)} cada</small>${line.note?`<em>${esc(line.note)}</em>`:""}</div><b>${money(Number(line.quantity)*Number(item.price))}</b><div class="mobile-item-controls"><div class="quantity-control"><button data-mobile-cart-minus="${id}">−</button><b>${line.quantity}</b><button data-mobile-cart-add="${id}">+</button></div><button data-cart-note="${id}">Observação</button><button class="danger" data-mobile-cart-remove="${id}">Remover</button></div></div>`}).join("");openModal(`<div class="mobile-cart-head"><div><span class="eyebrow">Pedido atual</span><h2>${cartQuantity()} itens</h2></div><button class="ghost" data-cart-clear>Limpar tudo</button></div><div class="mobile-cart-list">${rows}</div><div class="cart-total"><span>Total</span><b>${money(cartTotal())}</b></div><button class="primary checkout-button" data-open-checkout>Continuar para finalizar</button>`)}
