  const open=activeCash(),cashId=open?.[0]||"",cash=open?.[1];
  const shifts=cashId?entries(data.staff_shifts).filter(([,s])=>s.cash_session_id===cashId&&s.status!=="cancelled").sort((a,b)=>a[1].group.localeCompare(b[1].group)||a[1].employee_name.localeCompare(b[1].employee_name)):[];
  const teamShifts=shifts.filter(([,s])=>s.group!=="Evento"),events=shifts.filter(([,s])=>s.group==="Evento");
  const total=shifts.reduce((sum,[,s])=>sum+Number(s.daily_rate),0),paid=shifts.filter(([,s])=>s.status==="paid").reduce((sum,[,s])=>sum+Number(s.daily_rate),0);
  const rows=group=>shifts.filter(([,s])=>s.group===group).map(([id,s])=>`<article class="staff-team-card"><div class="staff-team-identity"><span class="staff-avatar">${esc(s.employee_name.trim().charAt(0).toUpperCase())}</span><div><b>${esc(s.employee_name)}</b><small>${esc(group==="Evento"?s.event_type||"Evento":group)}${s.note?` · ${esc(s.note)}`:""}</small></div></div><div class="staff-team-rate"><small>${group==="Evento"?"Cachê":"Diária"}</small><b>${money(s.daily_rate)}</b></div><span class="status ${s.status==="paid"?"printed":"pending"}">${s.status==="paid"?"Pago":"Pagamento pendente"}</span><div class="actions">${group==="Adega"&&open?`<button data-staff-access="${id}">Gerar acesso</button>`:""}${s.status!=="paid"?`<button class="primary" data-staff-pay="${id}">Registrar pagamento</button>${group==="Evento"?`<button class="danger" data-staff-cancel="${id}">Remover evento</button>`:""}`:""}</div></article>`).join("")||empty(group==="Evento"?"Nenhum evento cadastrado neste caixa.":`Nenhum funcionário da ${group.toLowerCase()} neste caixa.`);
  const closed=cashOptions.filter(([,c])=>c.status==="closed").slice(0,10);
  const history=closed.map(([id,c])=>{const team=entries(data.staff_shifts).filter(([,s])=>s.cash_session_id===id&&s.status!=="cancelled"),cost=team.reduce((sum,[,s])=>sum+Number(s.daily_rate),0);return`<div class="staff-shift-row"><div><b>${cashProject(c)} · ${date(c.opened_at)} até ${date(c.closed_at)}</b><small>${team.length} funcionário${team.length===1?"":"s"}</small></div><b>${money(cost)}</b></div>`}).join("")||empty("Nenhuma equipe anterior.");
