  return heading("Equipe e diárias")+(cash?`<p class="summary-period">Caixa aberto: <b>${date(cash.opened_at)} até agora</b></p>`:`<div class="notice">Abra o caixa para montar a equipe do turno. A lista começa vazia a cada novo caixa.</div>`)+`<div class="kpi-grid"><article class="kpi-card featured"><span>Na equipe</span><b>${teamShifts.length}</b></article><article class="kpi-card"><span>Custo total</span><b>${money(total)}</b></article><article class="kpi-card"><span>Pago</span><b>${money(paid)}</b></article><article class="kpi-card"><span>Pendente</span><b>${money(total-paid)}</b></article></div><div class="staff-groups"><section class="dashboard-card"><div class="dashboard-card-head"><h2>Adega</h2></div><div class="staff-team-list">${rows("Adega")}</div></section><section class="dashboard-card"><div class="dashboard-card-head"><h2>Cozinha</h2></div><div class="staff-team-list">${rows("Cozinha")}</div></section><section class="dashboard-card"><div class="dashboard-card-head"><div><h2>Eventos</h2><small class="muted">${events.length} cadastrado${events.length===1?"":"s"}</small></div><button class="primary" data-new-event ${open?"":"disabled"}>Cadastrar evento</button></div><div class="staff-team-list">${rows("Evento")}</div></section></div><section class="dashboard-card staff-directory staff-management"><div class="dashboard-card-head"><div><span class="eyebrow">Cadastro e escala do caixa</span><h2>Gerenciar funcionários</h2></div><button data-new-employee>+ Cadastrar funcionário</button></div><div class="staff-directory-list">${directory}</div></section><details class="dashboard-card staff-history"><summary><b>Ver equipes anteriores</b><span class="muted">Últimos caixas fechados</span></summary><div class="staff-directory-list">${history}</div></details>`;
