function stockStatus(item){if(!item.stock_controlled)return["Não controlado","legacy"];const qty=Number(item.stock_quantity||0),min=Number(item.stock_minimum||0);return qty<=0?["Esgotado","negative"]:qty<=min?["Estoque baixo","pending"]:["Normal","printed"]}
function stockPage(){const products=entries(data.menu).sort((a,b)=>a[1].name.localeCompare(b[1].name)),controlled=products.filter(([,p])=>p.stock_controlled),low=controlled.filter(([,p])=>Number(p.stock_quantity||0)<=Number(p.stock_minimum||0)),units=controlled.reduce((s,[,p])=>s+Number(p.stock_quantity||0),0),value=controlled.reduce((s,[,p])=>s+Number(p.stock_quantity||0)*Number(p.cost_price||0),0),movements=entries(data.stock_movements).sort((a,b)=>(b[1].created_at||"").localeCompare(a[1].created_at||"")).slice(0,50);return heading("Controle de estoque",`<button class="primary" data-stock-entry>+ Nova movimentação</button>`)+`<div class="kpi-grid stock-kpis"><article class="kpi-card featured"><span>Valor em estoque</span><b>${money(value)}</b><small>Baseado no custo cadastrado</small></article><article class="kpi-card"><span>Itens controlados</span><b>${controlled.length}</b><small>de ${products.length} produtos</small></article><article class="kpi-card"><span>Unidades disponíveis</span><b>${units.toLocaleString("pt-BR")}</b><small>Saldo físico total</small></article><article class="kpi-card ${low.length?'stock-alert-card':''}"><span>Precisam de atenção</span><b>${low.length}</b><small>Abaixo do mínimo ou esgotados</small></article></div>${low.length?`<div class="notice stock-warning"><b>Reposição necessária:</b> ${low.map(([,p])=>esc(p.name)).join(", ")}.</div>`:""}<section class="dashboard-card stock-products"><div class="dashboard-card-head"><div><span class="eyebrow">Posição atual</span><h2>Produtos</h2></div><span class="muted">Saldo, mínimo e custo</span></div><div class="stock-table-wrap"><table><thead><tr><th>Produto</th><th>Status</th><th>Saldo</th><th>Mínimo</th><th>Custo</th><th>Valor</th><th></th></tr></thead><tbody>${products.map(([id,p])=>{const status=stockStatus(p),qty=Number(p.stock_quantity||0);return`<tr><td><b>${esc(p.name)}</b><small>${esc(p.sku||p.barcode||p.supplier||"Sem dados adicionais")}</small></td><td><span class="status ${status[1]}">${status[0]}</span></td><td><b>${p.stock_controlled?`${qty} ${esc(p.unit||"un")}`:"—"}</b></td><td>${p.stock_controlled?Number(p.stock_minimum||0):"—"}</td><td>${p.stock_controlled?money(p.cost_price):"—"}</td><td>${p.stock_controlled?money(qty*Number(p.cost_price||0)):"—"}</td><td><div class="actions"><button data-stock-move="${id}" ${p.stock_controlled?'':'disabled'}>Movimentar</button><button data-stock-config="${id}">Configurar</button></div></td></tr>`}).join("")}</tbody></table></div></section><section class="dashboard-card stock-history"><div class="dashboard-card-head"><div><span class="eyebrow">Auditoria</span><h2>Movimentações recentes</h2></div><span class="muted">Últimas 50</span></div><div class="movement-list">${movements.map(([,m])=>`<div><span class="stock-movement-sign ${Number(m.signed_quantity)>0?'in':'out'}">${Number(m.signed_quantity)>0?'+':''}${Number(m.signed_quantity)}</span><div><b>${esc(m.product_name)}</b><small>${esc({sale:"Venda",in:"Entrada",out:"Saída",loss:"Perda",return:"Devolução",adjustment_in:"Ajuste"}[m.type]||"Movimentação")} · ${esc(m.reason||"Sem motivo")} · ${esc(m.responsible||"Sistema")} · ${date(m.created_at)}</small></div><b>${Number(m.balance_before)} → ${Number(m.balance_after)}</b></div>`).join("")||empty("Nenhuma movimentação registrada.")}</div></section>`}
function stockConfigDialog(id){const p=data.menu[id];if(!p)return;openModal(`<h2>Configurar estoque</h2><p class="muted">${esc(p.name)}</p><form data-form="stock-config"><input type="hidden" name="id" value="${id}"><label class="compare-toggle"><input type="checkbox" name="stock_controlled" value="true" ${p.stock_controlled?'checked':''}> Controlar saldo e bloquear venda sem estoque</label><div class="form-row"><div class="field"><label>Estoque mínimo</label><input name="stock_minimum" type="number" min="0" step=".001" value="${p.stock_minimum??0}" required></div><div class="field"><label>Unidade</label><select name="unit">${["un","garrafa","lata","caixa","kg","L"].map(v=>`<option ${p.unit===v?'selected':''}>${v}</option>`).join("")}</select></div></div><div class="form-row"><div class="field"><label>Custo unitário</label><input name="cost_price" type="number" min="0" step=".01" value="${p.cost_price??0}" required></div><div class="field"><label>SKU / código interno</label><input name="sku" value="${esc(p.sku||"")}"></div></div><div class="form-row"><div class="field"><label>Código de barras</label><input name="barcode" value="${esc(p.barcode||"")}"></div><div class="field"><label>Fornecedor</label><input name="supplier" value="${esc(p.supplier||"")}"></div></div><button class="primary checkout-button" type="submit">Salvar configuração</button></form>`)}
function stockMoveDialog(id=""){const products=entries(data.menu).filter(([,p])=>p.stock_controlled).sort((a,b)=>a[1].name.localeCompare(b[1].name)),selected=id||products[0]?.[0];if(!products.length){toast("Configure ao menos um produto para controlar estoque.",true);return}openModal(`<h2>Nova movimentação</h2><form data-form="stock-move"><div class="field"><label>Produto</label><select name="id" required>${products.map(([pid,p])=>`<option value="${pid}" ${pid===selected?'selected':''}>${esc(p.name)} · saldo ${Number(p.stock_quantity||0)} ${esc(p.unit||"un")}</option>`).join("")}</select></div><div class="field"><label>Tipo</label><select name="type" data-stock-type><option value="in">Entrada / compra</option><option value="out">Saída manual</option><option value="loss">Perda / avaria</option><option value="adjustment">Inventário / ajuste de saldo</option></select></div><div class="field" data-stock-quantity><label>Quantidade</label><input name="quantity" type="number" min=".001" step=".001" required></div><div class="field" data-stock-balance hidden><label>Novo saldo contado</label><input name="new_balance" type="number" min="0" step=".001"></div><div class="field"><label>Custo unitário nesta entrada (opcional)</label><input name="unit_cost" type="number" min="0" step=".01"></div><div class="field"><label>Responsável</label><input name="responsible" required></div><div class="field"><label>Motivo / documento</label><textarea name="reason" required placeholder="Ex.: NF 1234, contagem mensal, produto avariado..."></textarea></div><button class="primary checkout-button" type="submit">Registrar movimentação</button></form>`)}
function intelligentStockPage(){
  const items=entries(data.stock_items).sort((a,b)=>a[1].name.localeCompare(b[1].name));
  const low=items.filter(([,item])=>Number(item.stock_quantity||0)<=Number(item.stock_minimum||0));
  const available=items.filter(([,item])=>Number(item.stock_quantity||0)>0).length;
  const value=items.reduce((sum,[,item])=>sum+Number(item.stock_quantity||0)*Number(item.cost_price||0),0);
  const movements=entries(data.stock_movements).filter(([,movement])=>movement.stock_item_id).sort((a,b)=>(b[1].created_at||"").localeCompare(a[1].created_at||"")).slice(0,50);
  const openInventory=entries(data.inventories).find(([,inventory])=>inventory.status==="open");
  const current=stockView==="current",actions=current?"":`<div class="actions stock-page-actions"><button data-upload-invoice>Importar NF-e</button><button data-inventory="${openInventory?.[0]||''}">${openInventory?'Continuar inventário':'Iniciar inventário'}</button><button data-smart-stock-entry>+ Movimentação</button><button class="primary" data-new-stock-item>+ Cadastrar produto</button></div>`;
  const tabs=`<div class="tabs stock-view-tabs"><button data-stock-view="current" class="${current?'nav-active':''}">Estoque atual</button><button data-stock-view="register" class="${current?'':'nav-active'}">Cadastrar produtos</button></div>`;
  const rows=items.map(([id,item])=>{const qty=Number(item.stock_quantity||0),status=qty<=0?["Esgotado","negative"]:qty<=Number(item.stock_minimum||0)?["Baixo","pending"]:["Normal","printed"],packageLabel=stockPackageLabel(item),details=[item.supplier||item.sku||"Sem fornecedor",packageLabel].filter(Boolean).join(" · ");return`<tr><td class="stock-product-cell"><b>${esc(item.name)}</b><small>${esc(details)}</small></td><td><span class="status ${status[1]}">${status[0]}</span></td><td><b>${qty} ${esc(stockUnitLabel(item.unit,qty))}</b></td><td>${Number(item.stock_minimum||0)}</td><td>${money(item.cost_price)}</td><td>${money(qty*Number(item.cost_price||0))}</td>${current?"":`<td class="stock-action-cell"><div class="stock-row-actions"><button data-smart-stock-move="${id}">Movimentar</button><button data-edit-stock-item="${id}">Editar</button><button class="danger" data-delete-stock-item="${id}">Excluir</button></div></td>`}</tr>`}).join("")||`<tr><td colspan="${current?6:7}">${empty("Cadastre o primeiro produto do estoque, como Gin, energético, copo ou gelo.")}</td></tr>`;
  const history=movements.map(([,movement])=>`<div><span class="stock-movement-sign ${Number(movement.signed_quantity)>0?'in':'out'}">${Number(movement.signed_quantity)>0?'+':''}${Number(movement.signed_quantity)}</span><div><b>${esc(movement.product_name)}</b><small>${esc(movement.reason)} · ${esc(movement.responsible||"Sistema")} · ${date(movement.created_at)}</small></div><b>${Number(movement.balance_before)} → ${Number(movement.balance_after)}</b></div>`).join("")||empty("Nenhuma movimentação de insumos.");
  const summary=`<div class="kpi-grid stock-kpis"><article class="kpi-card featured"><span>Valor em estoque</span><b>${money(value)}</b></article><article class="kpi-card"><span>Produtos cadastrados</span><b>${items.length}</b></article><article class="kpi-card"><span>Com saldo disponível</span><b>${available}</b></article><article class="kpi-card ${low.length?'stock-alert-card':''}"><span>Reposição necessária</span><b>${low.length}</b></article></div>`;
  const table=`<section class="dashboard-card stock-products"><div class="dashboard-card-head"><div><span class="eyebrow">${current?'Posição atual':'Cadastro'}</span><h2>${current?'Estoque disponível':'Produtos do estoque'}</h2></div></div><div class="stock-table-wrap"><table><thead><tr><th>Produto</th><th>Status</th><th>Saldo</th><th>Mínimo</th><th>Custo médio</th><th>Valor</th>${current?'':'<th>Ações</th>'}</tr></thead><tbody>${rows}</tbody></table></div></section>`;
  const audit=`<section class="dashboard-card stock-history"><div class="dashboard-card-head"><div><span class="eyebrow">Auditoria</span><h2>Movimentações recentes</h2></div></div><div class="movement-list">${history}</div></section>`;
  return heading(current?"Estoque atual":"Cadastrar produtos",actions)+tabs+(current?summary+table+audit:`<div class="notice"><b>Cadastro e manutenção:</b> adicione produtos, configure seus dados e registre entradas, perdas, ajustes ou inventários.</div>${table}`);
}
function stockItemDialog(id=""){const i=data.stock_items[id]||{},quantity=id?"":"1",units=[["un","Unidade"],["lata","Lata"],["latão","Latão"],["garrafa","Garrafa"],["galão","Galão"],["pacote","Pacote"],["caixa","Caixa"],["fardo","Fardo"],["kg","Quilograma (kg)"],["g","Grama (g)"],["L","Litro (L)"],["ml","Mililitro (ml)"]];openModal(`<h2>${id?"Editar produto":"Cadastrar produto"}</h2><p class="muted">A quantidade representa quantas embalagens entram no estoque. O volume de cada embalagem é informado separadamente.</p><form data-form="stock-item"><input type="hidden" name="id" value="${id}"><div class="form-row"><div class="field"><label>Código do produto</label><input name="sku" value="${esc(i.sku||"")}" placeholder="Ex.: 008744" autofocus></div><div class="field"><label>Produto</label><input name="name" value="${esc(i.name||"")}" placeholder="Ex.: Skol Latão" required></div></div><div class="form-row"><div class="field"><label>${id?"Quantidade de entrada adicional":"Quantidade de entrada"}</label><input name="entry_quantity" type="number" min="0" step=".001" value="${quantity}" ${id?"":"required"}></div><div class="field"><label>Embalagem contada no estoque</label><select name="unit">${units.map(([value,label])=>`<option value="${value}" ${i.unit===value?'selected':''}>${label}</option>`).join("")}</select><small class="muted">Ex.: 25 latões = quantidade 25 e embalagem Latão.</small></div></div><div class="form-row"><div class="field"><label>Conteúdo de cada embalagem (opcional)</label><input name="package_size" type="number" min="0" step=".001" value="${i.package_size??''}" placeholder="Ex.: 473 ou 1"></div><div class="field"><label>Medida do conteúdo</label><select name="package_measure">${["ml","L","g","kg"].map(v=>`<option ${i.package_measure===v?'selected':''}>${v}</option>`).join("")}</select><small class="muted">Ex.: 473 ml por latão ou 1 L por garrafa.</small></div></div><div class="form-row"><div class="field"><label>Valor por embalagem</label><input name="cost_price" type="number" min="0" step=".01" value="${i.cost_price??0}" required></div><div class="field"><label>Valor total</label><div class="summary-value" data-manual-stock-total>${money(Number(quantity||0)*Number(i.cost_price||0))}</div></div></div><div class="form-row"><div class="field"><label>Fornecedor</label><input name="supplier" value="${esc(i.supplier||"")}" placeholder="Razão social ou nome"></div><div class="field"><label>Número do pedido/documento</label><input name="document_number" placeholder="Ex.: 032026072115"></div></div><div class="form-row"><div class="field"><label>Estoque mínimo (em embalagens)</label><input name="stock_minimum" type="number" min="0" step=".001" value="${i.stock_minimum??0}" required></div><div class="field"><label>Código de barras</label><input name="barcode" value="${esc(i.barcode||"")}"></div></div><div class="field"><label>Responsável pelo cadastro/entrada</label><input name="responsible" placeholder="Nome de quem conferiu" required></div><button class="primary checkout-button">${id?"Salvar produto":"Cadastrar produto e dar entrada"}</button></form>`)}
function invoiceUploadDialog(){pendingInvoice=null;openModal(`<h2>Importar nota ou pedido</h2><p class="muted">Selecione o XML oficial da NF-e ou um PDF de pedido/orçamento. Antes de cadastrar e dar entrada nos produtos, o sistema exibirá uma prévia para conferência.</p><div class="field"><label>Arquivo XML ou PDF</label><input type="file" accept=".xml,.pdf,text/xml,application/xml,application/pdf" data-invoice-file></div><div class="notice"><b>Importante:</b> no PDF, são considerados somente os produtos e as quantidades que estão entrando na adega. Informações auxiliares de embalagem, como galões por caixa e peso de cada volume, são ignoradas. Cada documento pode ser importado apenas uma vez.</div>`)}
function parseInvoiceXml(content){const xml=new DOMParser().parseFromString(content,"application/xml");if(xml.querySelector("parsererror"))throw new Error("O arquivo XML está inválido.");const text=(root,tag)=>root.getElementsByTagName(tag)[0]?.textContent?.trim()||"",info=xml.getElementsByTagName("infNFe")[0];if(!info)throw new Error("O arquivo não parece ser uma NF-e válida.");const unitMap={UN:"un",UND:"un",UNID:"un",CX:"caixa",CAIXA:"caixa",KG:"kg",G:"g",LT:"L",L:"L",ML:"ml",GF:"garrafa",GFA:"garrafa",LATA:"lata"},supplier=text(xml.getElementsByTagName("emit")[0]||xml,"xNome"),invoiceNumber=text(xml,"nNF"),rawKey=(info.getAttribute("Id")||text(xml,"chNFe")).replace(/^NFe/,"");if(!rawKey)throw new Error("Não foi possível identificar a chave da NF-e.");const items=[...xml.getElementsByTagName("det")].map(det=>{const product=det.getElementsByTagName("prod")[0]||det,rawUnit=text(product,"uCom").toUpperCase(),barcode=text(product,"cEAN");return{name:text(product,"xProd"),sku:text(product,"cProd"),barcode:/^(SEM GTIN|0)$/i.test(barcode)?"":barcode,unit:unitMap[rawUnit]||"un",quantity:Number(text(product,"qCom")),unit_cost:Number(text(product,"vUnCom"))}}).filter(item=>item.name&&Number.isFinite(item.quantity)&&item.quantity>0&&Number.isFinite(item.unit_cost));if(!items.length)throw new Error("Nenhum produto válido foi encontrado na NF-e.");return{invoice_key:rawKey,invoice_number:invoiceNumber,supplier,items}}
async function parseInvoicePdf(file){const body=new FormData();body.append("file",file);const response=await fetch("/api/invoice/pdf",{method:"POST",headers:{authorization:`Bearer ${token}`},body}),result=await response.json();if(!response.ok)throw new Error(result.error||"Não foi possível ler o PDF.");return result}
function invoicePreviewDialog(invoice){pendingInvoice=invoice;const total=invoice.items.reduce((sum,item)=>sum+item.quantity*item.unit_cost,0),rows=invoice.items.map(item=>`<tr><td><b>${esc(item.name)}</b><small>${esc(item.sku||item.barcode||"Sem código")}</small></td><td>${item.quantity} ${esc(item.unit)}</td><td>${money(item.unit_cost)}</td><td>${money(item.quantity*item.unit_cost)}</td></tr>`).join("");openModal(`<h2>Conferir ${invoice.source_type==="pdf"?"pedido":"NF-e"} ${esc(invoice.invoice_number||"")}</h2><p class="muted">Fornecedor: ${esc(invoice.supplier||"Não informado")} · ${invoice.items.length} produto${invoice.items.length===1?"":"s"}</p><div class="stock-table-wrap invoice-preview"><table><thead><tr><th>Produto</th><th>Quantidade</th><th>Custo unitário</th><th>Total</th></tr></thead><tbody>${rows}</tbody></table></div><div class="selected-items-total"><span>Total do documento</span><b>${money(total)}</b></div><form data-form="invoice-import"><div class="field"><label>Responsável pela importação</label><input name="responsible" required autofocus></div><button class="primary checkout-button">Importar e dar entrada no estoque</button></form>`)}
function smartStockMoveDialog(id=""){const items=entries(data.stock_items).sort((a,b)=>a[1].name.localeCompare(b[1].name)),selected=id||items[0]?.[0];if(!items.length){toast("Cadastre um insumo primeiro.",true);return}openModal(`<h2>Movimentar insumo</h2><form data-form="smart-stock-move"><div class="field"><label>Insumo</label><select name="id">${items.map(([sid,i])=>`<option value="${sid}" ${sid===selected?'selected':''}>${esc(i.name)} · ${Number(i.stock_quantity||0)} ${esc(i.unit||"un")}</option>`).join("")}</select></div><div class="field"><label>Tipo</label><select name="type" data-stock-type><option value="in">Entrada / compra</option><option value="out">Saída manual</option><option value="loss">Perda / avaria</option><option value="adjustment">Inventário / ajuste</option></select></div><div class="field" data-stock-quantity><label>Quantidade</label><input name="quantity" type="number" min=".001" step=".001" required></div><div class="field" data-stock-balance hidden><label>Novo saldo contado</label><input name="new_balance" type="number" min="0" step=".001"></div><div class="field"><label>Custo nesta entrada</label><input name="unit_cost" type="number" min="0" step=".01"></div><div class="field"><label>Responsável</label><input name="responsible" required></div><div class="field"><label>Motivo / documento</label><textarea name="reason" required></textarea></div><button class="primary checkout-button">Registrar</button></form>`)}
function recipeComponentRow(component={}){const items=entries(data.stock_items);return`<div class="recipe-component"><select name="stock_item_id" required><option value="">Selecione o insumo</option>${items.map(([id,i])=>`<option value="${id}" ${component.stock_item_id===id?'selected':''}>${esc(i.name)} (${esc(i.unit||"un")})</option>`).join("")}</select><input name="component_quantity" type="number" min=".0001" step=".0001" value="${component.quantity??""}" placeholder="Consumo por venda"><select name="component_unit"><option value="">Unidade do insumo</option><option>ml</option><option>L</option><option>g</option><option>kg</option><option>un</option><option>garrafa</option><option>lata</option></select><input name="component_yield" type="number" min=".01" step=".01" placeholder="Ou rendimento"><button type="button" class="danger" data-remove-component>×</button></div>`}
function recipeDialog(id){const p=data.menu[id],recipe=data.recipes[id];if(!p)return;if(!entries(data.stock_items).length){toast("Cadastre os produtos no estoque antes de configurar a baixa.",true);return}openModal(`<h2>Configurar baixa automática</h2><p><b>${esc(p.name)}</b></p><p class="muted">Informe quanto sai do estoque quando uma unidade deste item é vendida. Ex.: uma lata vendida desconta 1 lata; se uma garrafa rende 12 copões, informe rendimento 12 para descontar 1 ÷ 12 por copão.</p><form data-form="recipe"><input type="hidden" name="id" value="${id}"><div class="recipe-labels"><span>Produto do estoque</span><span>Consumo</span><span>Rendimento</span></div><div data-recipe-components>${(recipe?.components?.length?recipe.components:[{}]).map(recipeComponentRow).join("")}</div><button type="button" data-add-component>+ Adicionar produto/insumo</button><button class="primary checkout-button">Salvar baixa automática</button></form>`)}
function inventoryDialog(id=""){if(!id){openModal(`<h2>Iniciar inventário</h2><p class="notice">O sistema salvará o saldo esperado agora. Depois, informe a contagem física de cada insumo para ajustar as diferenças com auditoria.</p><form data-form="inventory-start"><div class="field"><label>Responsável</label><input name="responsible" required autofocus></div><div class="field"><label>Observação</label><textarea name="note" placeholder="Ex.: contagem de fechamento mensal"></textarea></div><button class="primary checkout-button">Abrir contagem</button></form>`);return}const inv=data.inventories[id];if(!inv)return;openModal(`<h2>Conferir inventário</h2><p class="muted">Aberto por ${esc(inv.responsible)} em ${date(inv.created_at)}. Conte fisicamente sem usar o saldo esperado como referência.</p><form data-form="inventory-finish"><input type="hidden" name="id" value="${id}"><div class="inventory-counts">${(inv.items||[]).map(entry=>{const item=data.stock_items[entry.stock_item_id];return item?`<div class="inventory-count"><div><b>${esc(item.name)}</b><small>${esc(item.unit||"un")}</small></div><input name="inventory_count" data-stock-item-id="${entry.stock_item_id}" type="number" min="0" step=".001" placeholder="Contagem física" required></div>`:""}).join("")}</div><div class="field"><label>Responsável pela conferência</label><input name="responsible" required></div><button class="primary checkout-button">Finalizar e ajustar diferenças</button></form>`)}
function cashSales(id){return entries(data.sales).filter(([,sale])=>sale.cash_session_id===id&&!sale.voided_at)}
function cashAccountPayments(id){return entries(data.account_payments).filter(([,payment])=>payment.cash_session_id===id&&!payment.voided_at)}
function cashLive(id,cash){const sales=cashSales(id),accountReceipts=cashAccountPayments(id),payments={};for(const[,sale]of sales)payments[sale.payment_method||"Não informado"]=(payments[sale.payment_method||"Não informado"]||0)+Number(sale.quantity)*Number(sale.price);for(const[,receipt]of accountReceipts)payments[receipt.payment_method]=(payments[receipt.payment_method]||0)+Number(receipt.amount);const supplies=(cash.movements||[]).filter(item=>item.type==="supply").reduce((sum,item)=>sum+Number(item.amount),0),withdrawals=(cash.movements||[]).filter(item=>item.type==="withdrawal").reduce((sum,item)=>sum+Number(item.amount),0),expected=Number(cash.opening_amount||0)+Number(payments.Dinheiro||0)+supplies-withdrawals,receivable=sales.filter(([,sale])=>sale.account_id||sale.payment_method==="Caderneta").reduce((sum,[,sale])=>sum+Number(sale.quantity)*Number(sale.price),0),payable=entries(data.staff_shifts).filter(([,shift])=>shift.cash_session_id===id&&shift.status!=="paid"&&shift.status!=="cancelled").reduce((sum,[,shift])=>sum+Number(shift.daily_rate||0),0);return{sales,accountReceipts,payments,supplies,withdrawals,expected,receivable,payable,total:Object.values(payments).reduce((sum,value)=>sum+value,0)}}
function openCashDialog(){openModal(`<h2>Abrir caixa</h2><p class="muted">Escolha a operação deste caixa. Vendas, pagamentos e equipe ficarão vinculados a ela; o estoque continuará compartilhado.</p><form data-form="cash-open"><div class="field"><label>Operação</label><select name="project_code" required><option value="adega_regular">Adega Camisa 10 · operação normal</option><option value="bagaco_laranja">🍊 Bagaço da Laranja · projeto especial</option></select></div><div class="field"><label>Responsável</label><input name="opened_by" required autofocus></div><div class="field"><label>Valor inicial em dinheiro</label><input name="opening_amount" type="number" min="0" step=".01" value="0" required></div><div class="field"><label>Observação (opcional)</label><textarea name="note"></textarea></div><button class="primary checkout-button" type="submit">Confirmar abertura</button></form>`)}
function cashMovementDialog(id,type){const withdrawal=type==="withdrawal";openModal(`<h2>${withdrawal?'Registrar sangria':'Registrar suprimento'}</h2><p class="muted">${withdrawal?'Dinheiro retirado da gaveta.':'Dinheiro adicionado à gaveta.'}</p><form data-form="cash-movement"><input type="hidden" name="id" value="${id}"><input type="hidden" name="type" value="${type}"><div class="field"><label>Valor</label><input name="amount" type="number" min=".01" step=".01" required autofocus></div><div class="field"><label>Responsável</label><input name="responsible" required></div><div class="field"><label>Motivo</label><textarea name="note" required></textarea></div><button class="primary checkout-button" type="submit">Registrar ${withdrawal?'sangria':'suprimento'}</button></form>`)}
function closeCashDialog(id){const cash=data.cash[id],live=cashLive(id,cash);openModal(`<h2>Fechar caixa</h2><div class="reconciliation-preview"><div><span>Valor inicial</span><b>${money(cash.opening_amount)}</b></div><div><span>Vendas em dinheiro</span><b>${money(live.payments.Dinheiro)}</b></div><div><span>Suprimentos</span><b>${money(live.supplies)}</b></div><div><span>Sangrias</span><b>− ${money(live.withdrawals)}</b></div><div class="expected"><span>Dinheiro esperado</span><b>${money(live.expected)}</b></div></div><form data-form="cash-close"><input type="hidden" name="id" value="${id}"><div class="field"><label>Dinheiro contado na gaveta</label><input name="counted_cash" type="number" min="0" step=".01" required autofocus></div><div class="field"><label>Responsável pelo fechamento</label><input name="closed_by" required></div><div class="field"><label>Observação (opcional)</label><textarea name="note"></textarea></div><button class="danger checkout-button" type="submit">Conferir e fechar caixa</button></form>`)}
function voidSaleDialog(id){openModal(`<h2>Cancelar lançamento</h2><p class="notice">O lançamento será preservado para auditoria e deixará de entrar nos cálculos atuais. Caixas já fechados não serão alterados.</p><form data-form="sale-void"><input type="hidden" name="id" value="${id}"><div class="field"><label>Responsável</label><input name="responsible" required autofocus></div><div class="field"><label>Justificativa</label><textarea name="reason" required></textarea></div><button class="danger checkout-button" type="submit">Confirmar cancelamento</button></form>`)}
function cashPage(){const open=activeCash(),closed=entries(data.cash).filter(([,cash])=>cash.status==="closed").sort((a,b)=>(b[1].closed_at||"").localeCompare(a[1].closed_at||""));let current;if(open){const[id,cash]=open,live=cashLive(id,cash);current=`<section class="cash-current"><div class="cash-session-head"><div><span class="eyebrow">Caixa em operação</span><h2>${esc(cash.opened_by||"Responsável não informado")}</h2><p class="muted">Aberto em ${date(cash.opened_at)}</p></div><div class="actions"><button data-cash-movement="supply" data-cash-id="${id}">+ Suprimento</button><button data-cash-movement="withdrawal" data-cash-id="${id}">− Sangria</button><button class="danger" data-close-cash="${id}">Fechar caixa</button></div></div><div class="kpi-grid cash-kpis"><article class="kpi-card featured"><span>Vendas do caixa</span><b>${money(live.total)}</b><small>${new Set(live.sales.map(([saleId,sale])=>sale.order_id||saleId)).size} pedidos</small></article><article class="kpi-card"><span>Dinheiro esperado</span><b>${money(live.expected)}</b><small>Na gaveta neste momento</small></article><article class="kpi-card"><span>Dinheiro a receber</span><b>${money(live.receivable)}</b><small>Vendas no fiado deste caixa</small></article><article class="kpi-card"><span>Dinheiro a pagar</span><b>${money(live.payable)}</b><small>Diárias pendentes da equipe</small></article></div><div class="dashboard-grid cash-detail-grid"><section class="dashboard-card"><div class="dashboard-card-head"><h3>Composição do dinheiro</h3></div><div class="cash-breakdown"><div><span>Troco inicial</span><b>${money(cash.opening_amount)}</b></div><div><span>Vendas em dinheiro</span><b>${money(live.payments.Dinheiro)}</b></div><div><span>Suprimentos</span><b class="positive-value">+ ${money(live.supplies)}</b></div><div><span>Sangrias</span><b class="negative-value">− ${money(live.withdrawals)}</b></div></div></section><section class="dashboard-card"><div class="dashboard-card-head"><h3>Movimentações</h3></div><div class="movement-list">${(cash.movements||[]).slice().reverse().map(movement=>`<div><span class="status ${movement.type==='supply'?'printed':'pending'}">${movement.type==='supply'?'Suprimento':'Sangria'}</span><div><b>${money(movement.amount)}</b><small>${esc(movement.responsible)} · ${esc(movement.note)} · ${date(movement.created_at)}</small></div></div>`).join("")||empty("Nenhuma movimentação neste caixa.")}</div></section></div></section>`}else current=`<div class="empty cash-empty"><h2>Nenhum caixa aberto</h2><p>Abra um caixa para começar a registrar vendas diretas.</p><button class="primary" data-open-cash>Abrir caixa</button></div>`;const archive=closed.map(([,cash])=>{const reconciled=cash.counted_cash!=null,difference=Number(cash.difference||0);return`<details class="cash-archive"><summary><div><b>${date(cash.opened_at)} até ${date(cash.closed_at)}</b><small>${esc(cash.opened_by||"Sem responsável")} → ${esc(cash.closed_by||"Sem responsável")}</small></div><span>${cash.sales_count||0} pedidos</span><b>${money(cash.total)}</b><span class="difference ${!reconciled?'legacy':difference===0?'ok':difference>0?'positive':'negative'}">${!reconciled?'Sem conferência':difference===0?'Conferido':`${difference>0?'+':''}${money(difference)}`}</span></summary><div class="cash-archive-body"><div class="operation-grid"><div><span>Inicial</span><b>${cash.opening_amount==null?'—':money(cash.opening_amount)}</b></div><div><span>Esperado</span><b>${cash.expected_cash==null?'—':money(cash.expected_cash)}</b></div><div><span>Contado</span><b>${cash.counted_cash==null?'—':money(cash.counted_cash)}</b></div></div><div class="cash-breakdown">${Object.entries(cash.payment_totals||{}).map(([method,total])=>`<div><span>${esc(method)}</span><b>${money(total)}</b></div>`).join("")}</div>${cash.closing_note?`<p class="notice">${esc(cash.closing_note)}</p>`:""}</div></details>`}).join("")||empty("Nenhum caixa fechado.");return heading("Controle de caixa",open?"":`<button class="primary" data-open-cash>Abrir caixa</button>`)+current+`<section class="cash-history"><div class="section-head"><div><span class="eyebrow">Arquivo</span><h2>Caixas anteriores</h2></div></div>${archive}</section>`}

document.addEventListener("click",async event=>{
  const el=event.target.closest("button");if(!el)return;
  if(module==="Frente de caixa")prepareFrontAlerts();
  try{
    if(el.dataset.module){module=el.dataset.module;page=null;if(module==="Cozinha")prepareKitchenAlerts();else knownKitchenOrderIds=null;if(module==="Frente de caixa")prepareFrontAlerts();else knownFrontKitchenStatuses=null;draw()}
    else if(el.dataset.page){page=el.dataset.page;if(kitchenViewOpen())prepareKitchenAlerts();else knownKitchenOrderIds=null;draw()}
    else if(el.hasAttribute("data-admin-logout")){token="";localStorage.removeItem("adminToken");sessionStorage.removeItem("adminToken");module=null;page=null;draw()}
    else if(el.hasAttribute("data-device-logout")){deviceToken="";deviceRole="";localStorage.removeItem("deviceAccessToken");localStorage.removeItem("deviceRole");module=null;page=null;draw()}
    else if(el.hasAttribute("data-owner-login")){staffDeviceManaged=false;localStorage.removeItem("staffDeviceManaged");module=null;page=null;draw()}
    else if(el.hasAttribute("data-home")||el.id==="homeBtn"){module=null;page=null;knownKitchenOrderIds=null;knownFrontKitchenStatuses=null;draw()}
    else if(el.hasAttribute("data-close"))closeModal();
    else if(el.dataset.cartAdd)changeCart(el.dataset.cartAdd,1);
    else if(el.dataset.cartMinus)changeCart(el.dataset.cartMinus,-1);
    else if(el.dataset.cartRemove){delete cart[el.dataset.cartRemove];saveCart();draw()}
    else if(el.dataset.mobileCartAdd){changeCart(el.dataset.mobileCartAdd,1);mobileCartDialog()}
    else if(el.dataset.mobileCartMinus){changeCart(el.dataset.mobileCartMinus,-1);mobileCartDialog()}
    else if(el.dataset.mobileCartRemove){delete cart[el.dataset.mobileCartRemove];saveCart();draw();mobileCartDialog()}
    else if(el.dataset.saleCategory){saleCategory=el.dataset.saleCategory;draw()}
    else if(el.dataset.frontKitchenFilter){frontKitchenFilter=el.dataset.frontKitchenFilter;draw()}
    else if(el.dataset.cartNote)cartNoteDialog(el.dataset.cartNote);
    else if(el.hasAttribute("data-cart-clear")&&confirm("Limpar todos os itens deste pedido?")){cart={};saveCart();if(modal.open)closeModal();draw()}
    else if(el.hasAttribute("data-open-checkout"))checkoutDialog();
    else if(el.hasAttribute("data-open-mobile-cart"))mobileCartDialog();
    else if(el.hasAttribute("data-new-order")){closeModal();draw()}
    else if(el.hasAttribute("data-enable-notifications")){
      prepareFrontAlerts();
      if(Notification.permission==="denied"){toast("Permita as notificações nas configurações do navegador.",true);return}
      const permission=await Notification.requestPermission();
      if(permission==="granted"){toast("Notificações de pedidos prontos ativadas.");draw()}else toast("As notificações não foram autorizadas.",true);
    }
    else if(el.hasAttribute("data-new-account"))accountFormDialog();
    else if(el.dataset.accountTypeView){accountTypeView=el.dataset.accountTypeView;draw()}
    else if(el.dataset.overviewProject){overviewProject=el.dataset.overviewProject;historyPage=1;draw()}
    else if(el.dataset.stockView){stockView=el.dataset.stockView;draw()}
    else if(el.hasAttribute("data-new-device"))deviceDialog();
    else if(el.dataset.revokeDevice&&confirm("Revogar o acesso deste dispositivo?")){await mutate({action:"device.revoke",id:el.dataset.revokeDevice},true);draw()}
    else if(el.dataset.editAccount)accountFormDialog(el.dataset.editAccount);
    else if(el.dataset.account)accountDialog(el.dataset.account);
    else if(el.dataset.accountPayment)accountPaymentDialog(el.dataset.accountPayment);
    else if(el.dataset.cancelAccountItem)cancelAccountItemDialog(el.dataset.cancelAccountItem,el.dataset.itemId,el.dataset.index);
    else if(el.dataset.paymentValue){const form=el.closest("form"),input=form?.elements.amount;if(input){input.value=el.dataset.paymentValue;updatePaymentRemaining(form)}}
    else if(el.dataset.printMode){
      if(el.dataset.printMode==="automatic"&&!confirm("Ativar impressão automática na impressora padrão deste computador?"))return;
      printMode=el.dataset.printMode;localStorage.setItem("printMode",printMode);draw();
    }
    else if(el.dataset.testPrint)await printOrder(el.dataset.testPrint,printMode);
    else if(el.dataset.requeuePrint){await mutate({action:"kitchen.requeue",id:el.dataset.requeuePrint});draw()}
    else if(el.dataset.kitchen){await mutate({action:"kitchen.status",id:el.dataset.kitchen,status:el.dataset.status,origin_token:originToken});draw()}
    else if(el.hasAttribute("data-new-menu"))menuDialog();
    else if(el.dataset.editMenu)menuDialog(el.dataset.editMenu);
    else if(el.hasAttribute("data-new-employee"))employeeDialog();
    else if(el.hasAttribute("data-new-event"))eventDialog();
    else if(el.dataset.editEmployee)employeeDialog(el.dataset.editEmployee);
    else if(el.dataset.staffAdd){const employee=data.employees[el.dataset.staffAdd];if(!employee)throw new Error("Funcionário não encontrado.");await mutate({action:"staff.shift.save",employee_id:el.dataset.staffAdd,daily_rate:employee.daily_rate,note:""},true);draw()}
    else if(el.hasAttribute("data-new-staff-shift"))staffShiftDialog();
    else if(el.dataset.staffAccess){const result=await mutate({action:"staff.access.create",id:el.dataset.staffAccess},true);const shift={...data.staff_shifts[el.dataset.staffAccess],id:el.dataset.staffAccess};staffAccessDialog(shift,result.access_token,result.expires_at)}
    else if(el.dataset.staffRevoke){await mutate({action:"staff.access.revoke",id:el.dataset.staffRevoke},true);closeModal();draw()}
    else if(el.dataset.staffPay)staffPayDialog(el.dataset.staffPay);
    else if(el.dataset.staffCancel){const shift=data.staff_shifts[el.dataset.staffCancel],message=shift?.group==="Evento"?"Remover este evento do caixa?":"Remover esta diária da equipe do caixa?";if(confirm(message)){await mutate({action:"staff.shift.cancel",id:el.dataset.staffCancel},true);draw()}}
    else if(el.dataset.deleteMenu&&confirm("Remover este item do cardápio?")){await mutate({action:"menu.delete",id:el.dataset.deleteMenu},true);draw()}
    else if(el.hasAttribute("data-stock-entry"))stockMoveDialog();
    else if(el.dataset.stockMove)stockMoveDialog(el.dataset.stockMove);
    else if(el.dataset.stockConfig)stockConfigDialog(el.dataset.stockConfig);
    else if(el.hasAttribute("data-new-stock-item"))stockItemDialog();
    else if(el.hasAttribute("data-upload-invoice"))invoiceUploadDialog();
    else if(el.dataset.editStockItem)stockItemDialog(el.dataset.editStockItem);
    else if(el.dataset.deleteStockItem&&confirm("Excluir este insumo?")){await mutate({action:"stock.item.delete",id:el.dataset.deleteStockItem},true);draw()}
    else if(el.hasAttribute("data-smart-stock-entry"))smartStockMoveDialog();
    else if(el.dataset.smartStockMove)smartStockMoveDialog(el.dataset.smartStockMove);
    else if(el.dataset.recipe)recipeDialog(el.dataset.recipe);
    else if(el.hasAttribute("data-inventory"))inventoryDialog(el.dataset.inventory);
    else if(el.hasAttribute("data-add-component")){const form=el.closest("form"),list=form.querySelector("[data-recipe-components]");list.insertAdjacentHTML("beforeend",form.dataset.form==="menu"?menuRecipeComponentRow():recipeComponentRow());form.querySelector(".recipe-empty-hint")?.remove()}
    else if(el.hasAttribute("data-remove-component"))el.closest(".recipe-component").remove();
    else if(el.dataset.deleteSale)voidSaleDialog(el.dataset.deleteSale);
    else if(el.dataset.calendarDay){summaryFilter=`day:${el.dataset.calendarDay}`;summaryCalendarMonth=el.dataset.calendarDay.slice(0,7);historyPage=1;draw()}
    else if(el.dataset.calendarNav){const current=new Date(`${summaryCalendarMonth}-01T12:00:00`);current.setMonth(current.getMonth()+Number(el.dataset.calendarNav));summaryCalendarMonth=`${current.getFullYear()}-${String(current.getMonth()+1).padStart(2,"0")}`;draw()}
    else if(el.dataset.openDatePicker){const input=el.form?.elements[el.dataset.openDatePicker];if(input){input.focus();if(typeof input.showPicker==="function")input.showPicker()}}
    else if(el.hasAttribute("data-clear-summary-range")){summaryFilter=`day:${localDay(new Date())}`;historyPage=1;draw()}
    else if(el.dataset.summary){summaryFilter=el.dataset.summary;draw()}
    else if(el.dataset.historyPage){historyPage=Number(el.dataset.historyPage);draw()}
    else if(el.hasAttribute("data-open-cash"))openCashDialog();
    else if(el.dataset.cashMovement)cashMovementDialog(el.dataset.cashId,el.dataset.cashMovement);
    else if(el.dataset.closeCash)closeCashDialog(el.dataset.closeCash);
  }catch(error){toast(error.message,true)}
});

document.addEventListener("submit",async event=>{
  event.preventDefault();const form=event.target;const fd=Object.fromEntries(new FormData(form));
  try{
    if(form.dataset.form==="login"){
      const remember=Boolean(fd.remember),response=await fetch("/api/login",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({password:fd.password,remember})}),result=await response.json();if(!response.ok)throw new Error(result.error);token=result.token;if(remember)localStorage.setItem("adminToken",token);else sessionStorage.setItem("adminToken",token);module=null;page=null;await load(false);draw();return;
    }
    if(form.dataset.form==="device-claim"){const response=await fetch("/api/device/claim",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({code:fd.code})}),result=await response.json();if(!response.ok)throw new Error(result.error);deviceToken=result.access_token;deviceRole=result.role;localStorage.setItem("deviceAccessToken",deviceToken);localStorage.setItem("deviceRole",deviceRole);module=null;page=null;await load(false);draw();return}
    if(form.dataset.form==="device-create"){const result=await mutate({action:"device.create",label:fd.label,role:fd.role},true);modalBody.innerHTML=`<div class="modal-content device-code-result"><span class="eyebrow">Código temporário</span><h2>${esc(fd.label)}</h2><b class="device-code">${esc(result.code)}</b><p>Digite este código no dispositivo em até 10 minutos.</p><button class="primary checkout-button" data-close>Concluir</button></div>`;draw();return}
    if(form.dataset.form==="summary-range"){
      if(fd.date_from>fd.date_to)throw new Error("A data inicial deve ser anterior à data final.");
      summaryFilter=`range:${fd.date_from},${fd.date_to}`;historyPage=1;draw();return;
    }
    if(form.dataset.form==="history-filter"){
      historyQuery=fd.query.trim();historyPayment=fd.payment;historyPage=1;draw();return;
    }
    if(form.dataset.form==="cart-note"){
      cart[fd.id]={...cart[fd.id],note:fd.note.trim()};saveCart();draw();if(fd.return_to_cart)mobileCartDialog();else closeModal();return;
    }
    if(form.dataset.form==="cash-open"){await mutate({action:"cash.open",project_code:fd.project_code,opened_by:fd.opened_by,opening_amount:fd.opening_amount,note:fd.note},true);if(fd.project_code==="bagaco_laranja"){closeModal();app.classList.add("bagaco-operation");nav.innerHTML="";app.innerHTML=bagacoLandingPage();setTimeout(()=>{module="Admin";page="cash";draw()},4000);return}}
    if(form.dataset.form==="cash-movement")await mutate({action:"cash.movement",id:fd.id,type:fd.type,amount:fd.amount,responsible:fd.responsible,note:fd.note},true);
    if(form.dataset.form==="cash-close")await mutate({action:"cash.close",id:fd.id,counted_cash:fd.counted_cash,closed_by:fd.closed_by,note:fd.note},true);
    if(form.dataset.form==="sale-void")await mutate({action:"sale.void",id:fd.id,responsible:fd.responsible,reason:fd.reason},true);
    if(form.dataset.form==="account")await mutate({action:fd.id?"account.update":"account.create",...fd,blocked:Boolean(fd.blocked)});
    if(form.dataset.form==="account-payment"){const allocations=[...form.querySelectorAll("[data-allocation-item]")].map(input=>({item_id:input.dataset.allocationItem,quantity:Number(input.value||0)})).filter(item=>item.quantity>0),result=await mutate({action:"account.receivePayment",...fd,allocations});if(result.closed){closeModal();toast("Mesa totalmente quitada.");draw()}else{accountDialog(fd.id);draw()}return}
    if(form.dataset.form==="account-cancel-item"){await mutate({action:"account.cancelItem",...fd});accountDialog(fd.id);draw();return}
    if(form.dataset.form==="menu"){const components=[...form.querySelectorAll(".menu-recipe-component")].map(row=>({stock_item_id:row.querySelector("[name='stock_item_id']").value,quantity:Number(row.querySelector("[name='component_quantity']").value),unit:""}));if(components.some(component=>!component.stock_item_id||!Number.isFinite(component.quantity)||component.quantity<=0))throw new Error("Confira os insumos e as quantidades utilizadas.");const result=await mutate({action:fd.id?"menu.update":"menu.create",id:fd.id,name:fd.name,price:fd.price,category:fd.category},true);await mutate({action:"recipe.save",id:result.id,components},true);}
    if(form.dataset.form==="employee")await mutate({action:"employee.save",...fd},true);
    if(form.dataset.form==="event")await mutate({action:"event.save",...fd},true);
    if(form.dataset.form==="staff-shift")await mutate({action:"staff.shift.save",...fd},true);
    if(form.dataset.form==="staff-pay")await mutate({action:"staff.shift.pay",...fd},true);
    if(form.dataset.form==="stock-config")await mutate({action:"stock.configure",...fd,stock_controlled:Boolean(fd.stock_controlled)},true);
    if(form.dataset.form==="stock-move")await mutate({action:"stock.move",...fd},true);
    if(form.dataset.form==="stock-item"){const quantity=Number(fd.entry_quantity||0);if(!Number.isFinite(quantity)||quantity<0)throw new Error("Informe uma quantidade de entrada válida.");const saved=await mutate({action:"stock.item.save",id:fd.id,name:fd.name,unit:fd.unit,package_size:fd.package_size,package_measure:fd.package_measure,stock_minimum:fd.stock_minimum,cost_price:fd.cost_price,supplier:fd.supplier,sku:fd.sku,barcode:fd.barcode},true);if(quantity>0)await mutate({action:"stock.item.move",id:saved.id,type:"in",quantity,unit_cost:fd.cost_price,responsible:fd.responsible,reason:fd.document_number?`Entrada manual · Pedido/Documento ${fd.document_number}`:"Entrada manual"},true);}
    if(form.dataset.form==="invoice-import"){if(!pendingInvoice)throw new Error("Selecione novamente o XML da NF-e.");const result=await mutate({action:"stock.invoice.import",...pendingInvoice,responsible:fd.responsible},true);pendingInvoice=null;closeModal();draw();toast(`${result.created} produto(s) cadastrado(s) e ${result.updated} atualizado(s).`);return}
    if(form.dataset.form==="smart-stock-move")await mutate({action:"stock.item.move",...fd},true);
    if(form.dataset.form==="recipe"){const components=[...form.querySelectorAll(".recipe-component")].map(row=>{const direct=Number(row.querySelector("[name='component_quantity']").value),yieldValue=Number(row.querySelector("[name='component_yield']").value);return{stock_item_id:row.querySelector("[name='stock_item_id']").value,quantity:direct>0?direct:yieldValue>0?1/yieldValue:0,unit:row.querySelector("[name='component_unit']").value}}).filter(c=>c.stock_item_id&&c.quantity>0);await mutate({action:"recipe.save",id:fd.id,components},true)}
    if(form.dataset.form==="inventory-start"){const result=await mutate({action:"inventory.start",...fd},true);inventoryDialog(result.id);draw();return}
    if(form.dataset.form==="inventory-finish"){const counts=[...form.querySelectorAll("[name='inventory_count']")].map(input=>({stock_item_id:input.dataset.stockItemId,counted:input.value}));await mutate({action:"inventory.finish",id:fd.id,responsible:fd.responsible,counts},true)}
    if(form.dataset.form==="account-item"){
      const item=data.menu[fd.menu_id];await mutate({action:"account.addItem",id:fd.id,menu_id:fd.menu_id,description:item?.name||fd.description,price:item?.price??fd.price,quantity:fd.quantity,note:fd.note,print_order:Boolean(item&&category(item)==="Comidas"),origin_token:originToken});
    }
    if(form.dataset.form==="checkout"){
      if(checkoutSubmitting)return;checkoutSubmitting=true;const submit=form.querySelector("button[type='submit']"),total=cartTotal(),quantity=cartQuantity(),hasFood=cartLines().some(([id])=>category(data.menu[id])==="Comidas");submit.disabled=true;submit.textContent="Finalizando...";
      try{const result=await mutate({action:"sale.checkout",items:cartLines().map(([menu_id,line])=>({menu_id,quantity:line.quantity,note:line.note||""})),customer_name:fd.destination==="account"?fd.customer_name:fd.sale_customer_name,payment_method:fd.payment_method,note:fd.note,destination:fd.destination,account_id:fd.account_id,origin_token:originToken});cart={};saveCart();draw();modalBody.innerHTML=`<div class="modal-content order-success"><span class="success-icon">✓</span><h2>Pedido confirmado</h2><b class="order-number">#${esc(result.id.slice(0,8).toUpperCase())}</b><div class="success-summary"><div><span>Itens</span><b>${quantity}</b></div><div><span>Total</span><b>${money(total)}</b></div><div><span>Destino</span><b>${fd.destination==="account"?'Fiado':esc(fd.payment_method)}</b></div></div>${hasFood?`<p class="notice">Comanda enviada para a fila de impressão da cozinha.</p>`:""}<button class="primary checkout-button" data-new-order>Novo pedido</button></div>`;return}finally{checkoutSubmitting=false;if(form.isConnected){submit.disabled=false;submit.textContent=`Confirmar pedido · ${money(total)}`}}
    }
    closeModal();draw();
  }catch(error){toast(error.message,true)}
});

document.addEventListener("change",async event=>{
  if(event.target.matches("[data-invoice-file]")){try{const file=event.target.files?.[0];if(!file)return;toast(file.type==="application/pdf"||/\.pdf$/i.test(file.name)?"Lendo o PDF...":"Lendo o XML...");const invoice=file.type==="application/pdf"||/\.pdf$/i.test(file.name)?await parseInvoicePdf(file):parseInvoiceXml(await file.text());invoicePreviewDialog(invoice)}catch(error){pendingInvoice=null;toast(error.message,true)}return}
  if(event.target.matches("[data-summary-cash]")&&event.target.value){summaryFilter=event.target.value;draw()}
  if(event.target.matches("[data-front-kitchen-select]")){frontKitchenFilter=event.target.value;draw()}
  if(event.target.matches("[data-staff-cash]")){staffCashId=event.target.value;draw()}
  if(event.target.matches("[data-form='staff-shift'] [name='employee_id']")){const option=event.target.selectedOptions[0];event.target.form.elements.daily_rate.value=option?.dataset.rate||""}
  if(event.target.matches(".menu-recipe-component [name='stock_item_id']"))event.target.closest(".menu-recipe-component").querySelector("[data-component-unit]").textContent=event.target.selectedOptions[0]?.dataset.unit||"—";
  if(event.target.matches("[data-form='checkout'] [name='destination'],[data-form='checkout'] [name='account_id'],[data-form='checkout'] [name='payment_method']"))updateCheckoutFields(event.target.form)
  if(event.target.matches("[data-form='account-payment'] [name='settlement_type'],[data-form='account-payment'] [data-allocation-toggle]"))updateAccountPaymentFields(event.target.form)
  if(event.target.matches("[data-stock-type]")){const form=event.target.form,adjust=event.target.value==="adjustment";form.querySelector("[data-stock-quantity]").hidden=adjust;form.querySelector("[data-stock-balance]").hidden=!adjust;form.elements.quantity.required=!adjust;form.elements.new_balance.required=adjust}
});

document.addEventListener("input",event=>{
  if(event.target.matches("[data-product-search]")){saleSearch=event.target.value;draw();requestAnimationFrame(()=>{const input=document.querySelector("[data-product-search]");if(input){input.focus();input.setSelectionRange(saleSearch.length,saleSearch.length)}})}
  if(event.target.matches("[data-form='stock-item'] [name='entry_quantity'],[data-form='stock-item'] [name='cost_price']")){const form=event.target.form,total=Number(form.elements.entry_quantity.value||0)*Number(form.elements.cost_price.value||0);form.querySelector("[data-manual-stock-total]").textContent=money(Number.isFinite(total)?total:0)}
  if(event.target.matches("[data-form='account-payment'] [name='amount']"))updatePaymentRemaining(event.target.form)
  if(event.target.matches("[data-form='account-payment'] [name='split_people'],[data-form='account-payment'] [data-allocation-item],[data-form='account-payment'] [data-allocation-toggle]"))updateAccountPaymentFields(event.target.form)
  if(event.target.matches("[data-form='checkout'] [name='cash_received']"))updateCheckoutChange(event.target.form)
});

document.addEventListener("keydown",event=>{
  if(event.key==="Escape"&&modal.open){closeModal();return}
  if(module!=="Frente de caixa"||page!=="sales")return;
  if(event.key==="F2"){event.preventDefault();document.querySelector("[data-product-search]")?.focus()}
  if(event.key==="F4"&&cartLines().length){event.preventDefault();checkoutDialog()}
});

modal.addEventListener("click",event=>{if(event.target===modal)closeModal()});
document.addEventListener("click",event=>{
  const summary=event.target.closest(".kitchen-history > summary");
  if(!summary)return;
  event.preventDefault();
  kitchenHistoryOpen=!kitchenHistoryOpen;
  summary.parentElement.open=kitchenHistoryOpen;
});
document.addEventListener("toggle",event=>{
  if(event.target.matches(".front-kitchen-history"))frontKitchenHistoryOpen=event.target.open;
},true);
async function start(){try{if(inviteToken)await claimInvite();if(token||deviceToken||originToken)await load();else draw()}catch(error){localStorage.removeItem("staffAccessToken");originToken="";module=null;page=null;draw();toast(error.message,true)}}
start();
